قفسهٔ «نان و نیم‌فروشی» خالی می‌ماند ولی فروش هم ضعیف است. ریشه کجاست؟ (مدیر خرید — زنجیرهٔ شهروند)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sellthrough",
      "description": "نرخ فروش از خرید (پیشروی کالا)",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "sellthrough_pct"
      ]
    },
    {
      "dataset": "supplier_scorecard",
      "description": "عملکرد تأمین‌کنندگان",
      "dimensions": [
        "supplier",
        "month"
      ],
      "measures": [
        "on_time_rate",
        "rejection_rate",
        "fill_rate"
      ]
    },
    {
      "dataset": "purchase_orders",
      "description": "سفارش خرید به تفکیک تأمین‌کننده و دسته",
      "dimensions": [
        "supplier",
        "category",
        "month"
      ],
      "measures": [
        "amount_m",
        "qty_ton",
        "unit_price_k"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "sellthrough",
      "description": "پیشروی فروش از خرید",
      "formula": "فروش تقسیم بر خرید دوره",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "fill_rate",
      "description": "پرشدن کامل سفارش",
      "formula": "اقلام تحویل‌شده تقسیم بر سفارش",
      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    }
  ],
  "business_context": [
    "هدف پیشروی کالا ۸۵٪ تا پایان دوره",
    "شاخص قیمت بازار ماهانه برای دسته‌های اصلی",
    "خرید مرکزی برای ۱۲۰ شعبه با مرکز توزیع واحد"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sellthrough",
    "filters": {
      "category": "نان و نیم‌فروشی",
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
