{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_scorecard",
    "filters": {
      "supplier": [
        "تأمین‌کنندهٔ ب",
        "تأمین‌کنندهٔ ت"
      ],
      "period": "last_3_months"
    }
  }
}

